# Exact rectilinear Steiner tree length on the Hanan grid using subset DP.
pts=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]
xs=sorted(set(c for r,c in pts)); ys=sorted(set(r for r,c in pts))
V=[(r,c) for r in ys for c in xs]; n=len(V); ix={p:i for i,p in enumerate(V)}
adj=[[] for _ in V]
for i,(r,c) in enumerate(V):
 for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
  if (rr,cc) in ix: adj[i].append((ix[(rr,cc)],1))
# all-pairs shortest path
D=[[10**6]*n for _ in V]
for s in range(n):
 D[s][s]=0
 for _ in range(n):
  for u in range(n):
   for v,w in adj[u]: D[s][v]=min(D[s][v],D[s][u]+w)
# DP over terminal subsets; closure via shortest paths
N=1<<len(pts); dp=[[10**6]*n for _ in range(N)]
for k,p in enumerate(pts): dp[1<<k][ix[p]]=0
for mask in range(1,N):
 sub=(mask-1)&mask
 while sub:
  oth=mask^sub
  if oth and sub<oth:
   for v in range(n): dp[mask][v]=min(dp[mask][v],dp[sub][v]+dp[oth][v])
  sub=(sub-1)&mask
 # shortest path closure by min over w
 old=dp[mask][:]
 for v in range(n): dp[mask][v]=min(old[w]+D[w][v] for w in range(n))
print('Hanan coords',ys,xs,'opt length',min(dp[-1]))
# Our horizontal trunk length
print('horizontal network length',11+(5+2+2+4))

