adj=[[] for _ in V]
for i,(r,c) in enumerate(V):
 for rr,cc in [(r, x) for x in xs]+[(y,c) for y in ys]:
  j=idx[(rr,cc)]
  if j!=i and (rr==r or cc==c): adj[i].append((j,abs(rr-r)+abs(cc-c)))
# Floyd
D=[[abs(r-r2)+abs(c-c2) for r2,c2 in V] for r,c in V]
for k in range(n):
 for i in range(n):
  for j in range(n): D[i][j]=min(D[i][j],D[i][k]+D[k][j])
N=1<<len(pts); inf=10**6; dp=[[inf]*n for _ in range(N)]
for k,p in enumerate(pts):dp[1<<k][idx[p]]=0
for mask in range(1,N):
 sub=(mask-1)&mask
 while sub:
  oth=mask^sub
  if oth and sub<oth:
   for v in range(n):dp[mask][v]=min(dp[mask][v],dp[sub][v]+dp[oth][v])
  sub=(sub-1)&mask
 for v in range(n):dp[mask][v]=min(dp[mask][v],min(dp[mask][w]+D[w][v] for w in range(n)))
print('minimum network length',min(dp[-1]))
